package dev.veltraph.client.navigation;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** CORE8 captured contact/prior pose with an explicitly reconstructed allowed prior air sample. */
class GroundJumpObservedLandingTest {
    private static final Vec3 TAKEOFF=new Vec3(.5078732762509196,71,7.157010263233348),TARGET=new Vec3(.5,72,8.5),BEFORE=new Vec3(.4995369618211231,72.02442408821369,8.465825096190509),ACTUAL=new Vec3(.4985574434817092,72,8.642079610248448),VELOCITY=new Vec3(-.0008913617145555579,-.0784000015258789,.16039161241518393);
    private static GroundJumpObservedLanding.AirSample sample(){var priorVelocity=new Vec3(VELOCITY.x()/(double).91F,GroundJumpLandingForecast.ordinaryVertical(8).orElseThrow().velocity(),VELOCITY.z()/(double).91F-.0196);return new GroundJumpObservedLanding.AirSample(1000,1008,TAKEOFF,TARGET,BEFORE,priorVelocity,.1,true,false);}
    private static java.util.Optional<GroundJumpObservedLanding.Contact> contact(GroundJumpObservedLanding.AirSample prior,int tick,boolean ground,Vec3 position,Vec3 velocity,Vec3 target){return GroundJumpObservedLanding.contact(prior,1000,tick,ground,false,position,velocity,TAKEOFF,target,.1);}
    @Test void actualGroundContactIsOutsideOldVelocityCapAndAirForecastButInsideOwnedContactTransition(){assertTrue(Math.hypot(VELOCITY.x(),VELOCITY.z())>.16);assertFalse(GroundLocomotionMotion.landingMotion(ACTUAL,VELOCITY,TARGET,.1));assertFalse(GroundLocomotionMotion.airborne(ACTUAL,VELOCITY,TAKEOFF,TARGET,.1));var c=contact(sample(),1009,true,ACTUAL,VELOCITY,TARGET).orElseThrow();assertEquals(9,c.nativeSteps());assertTrue(c.horizontalBound()>=Math.hypot(VELOCITY.x(),VELOCITY.z()));assertTrue(ACTUAL.horizontalDistanceTo(c.coast())<=GroundJumpObservedLanding.maximumCoastDistance());}
    @Test void actualGroundFlagAndImmediatelyPreviousPublishedAirReceiptAreRequired(){assertTrue(contact(null,1009,true,ACTUAL,VELOCITY,TARGET).isEmpty());assertTrue(contact(sample(),1009,false,ACTUAL,VELOCITY,TARGET).isEmpty());assertTrue(contact(sample(),1010,true,ACTUAL,VELOCITY,TARGET).isEmpty());assertTrue(contact(sample(),1008,true,ACTUAL,VELOCITY,TARGET).isEmpty());}
    @Test void wrongTargetIssueAgeOrSprintCannotBorrowCollisionRecognition(){assertTrue(contact(sample(),1009,true,ACTUAL,VELOCITY,new Vec3(.5,72,8.6)).isEmpty());assertTrue(GroundJumpObservedLanding.contact(sample(),999,1009,true,false,ACTUAL,VELOCITY,TAKEOFF,TARGET,.1).isEmpty());assertTrue(GroundJumpObservedLanding.contact(sample(),1000,1009,true,true,ACTUAL,VELOCITY,TAKEOFF,TARGET,.1).isEmpty());}
    @Test void foreignHorizontalOrVerticalImpulseAndDisplacementRemainRejected(){assertTrue(contact(sample(),1009,true,ACTUAL,new Vec3(0,-.0784,.2),TARGET).isEmpty());assertTrue(contact(sample(),1009,true,ACTUAL,new Vec3(VELOCITY.x(),-.3,VELOCITY.z()),TARGET).isEmpty());assertTrue(contact(sample(),1009,true,new Vec3(ACTUAL.x(),72,ACTUAL.z()+.02),VELOCITY,TARGET).isEmpty());}
    @Test void brakingPublicationCannotExplainAnAddedForwardAirImpulse(){var old=sample();var neutral=new GroundJumpObservedLanding.AirSample(old.issuedTick(),old.tick(),old.takeoff(),old.target(),old.position(),old.velocity(),old.speed(),false,false);assertTrue(contact(neutral,1009,true,ACTUAL,VELOCITY,TARGET).isEmpty());}
    @Test void stoppingCoastUsesNormalFrictionTailWithoutRaisingOriginalAirborneCaps(){var c=contact(sample(),1009,true,ACTUAL,VELOCITY,TARGET).orElseThrow();double multiplier=.600001*(double).91F;assertEquals(VELOCITY.z()/(1-multiplier),c.coast().z()-ACTUAL.z(),1e-12);assertTrue(c.coast().z()>TARGET.z()+.35);assertFalse(GroundLocomotionMotion.airborne(ACTUAL,VELOCITY,TAKEOFF,TARGET,.1));}
}
